entries[172363] = { ["name"] = "Ring - Lehre der Meisterschaft", ["text"] = "Benutzen: Einen Ring dauerhaft verzaubern, sodass die Meisterschaft um 43 erhöht wird. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:" }
