entries[172365] = { ["name"] = "Waffe - Aufgestiegene Lebenskraft", ["text"] = "Benutzen: Eine Waffe dauerhaft verzaubern, sodass sie manchmal Eure erhaltene Heilung für 10 Sek. um 12% erhöht, wenn Ihr Schaden erleidet. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:" }
entries[172366] = { ["name"] = "Waffe - Himmlische Führung", ["text"] = "Benutzen: Eine Waffe dauerhaft verzaubern, sodass bei Angriffen oder dem Einsatz von Zaubern und Fähigkeiten manchmal Euren Primärwert um 5% erhöht wird. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:" }
entries[172367] = { ["name"] = "Waffe - Ewige Anmut", ["text"] = "Benutzen: Eine Waffe dauerhaft verzaubern, sodass sie manchmal beim Ziel Eurer hilfreichen Zauber und Fähigkeiten einen Heilungsschub in Höhe von [(97 / 100 * Max(Angriffskraft, Zaubermacht) * (1 + Vielseitigkeit))] Gesundheit bewirkt, die gleichmäßig auf Verbündete in der Nähe aufgeteilt wird. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:" }
entries[172368] = { ["name"] = "Waffe - Sündhafte Offenbarung", ["text"] = "Benutzen: Eine Waffe dauerhaft verzaubern, sodass Eure Angriffe manchmal eine Sünde des Ziels offenbaren, durch die es 10 Sek. lang 6% mehr Schaden durch Euch erleidet. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:" }
entries[172370] = { ["name"] = "Waffe - Lichtlose Kraft", ["text"] = "Benutzen: Eine Waffe dauerhaft verzaubern, sodass eine Chance besteht, beim Einsatz von Offensivzaubern und -fähigkeiten eine Welle aus Schattenenergie nach vorn zu entsenden, die die ersten 5 Gegner in ihrer Bahn trifft. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:" }
entries[172371] = { ["name"] = "Mal von Vashj", ["text"] = "Questgegenstand\nBenutzen: Durch das Vorzeigen dieses Mals erlangt Ihr das Vertrauen der Mitglieder des Hauses der Augen. (5 Sek. Abklingzeit)" }
