entries[172383] = { ["name"] = "Gesammelter Flutblütenhonig", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt eine Allianz-Rasse\nDer Honigrückenschwarm hat keinen Honig mehr. Kommt nächste Woche wieder.\n\"'Bitte teilt diesen Honig mit Euren Freunden... und natürlich Eurer Biene. Danke!' - Ingmar der Imker\"" }
entries[172405] = { ["name"] = "Foliant der Verhexung: Lebendiger Honig", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schamane\nBenutzen: Lehrt 'Verhexen: Lebendiger Honig'.\nVerwandelt den Gegner für 1 Min. in lebendigen Honig. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden.\nVerkaufspreis:" }
entries[172406] = { ["name"] = "Handschuhe - Sammeln der Schattenlande", ["text"] = "Benutzen: Handschuhe dauerhaft verzaubern, sodass die Geschwindigkeit des Sammelns in den Schattenlanden erhöht wird.\nVerkaufspreis:" }
