entries[172448] = { ["name"] = "Superklebriger Honig", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenutzen: Eure Finger sind voll mit Honig und unglaublich klebrig. Hält 15 Min. an. (2 Sek. Abklingzeit)\n\"Derart klebriger Honig könnte noch für etwas nützlich sein...\"\nVerkaufspreis:" }
entries[172449] = { ["name"] = "Glyphe 'Üppige Bewirtung'", ["text"] = "Klassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer herbeigezaubertes Essen ist jetzt noch üppiger.\nVerkaufspreis:" }
entries[172450] = { ["name"] = "Technik: Glyphe 'Üppige Bewirtung'", ["text"] = "Einzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Üppige Bewirtung' schreibt.\nBenötigt Inschriftenkunde von Kul Tiras (175)\nVerkaufspreis:\nGlyphe 'Üppige Bewirtung'\nKlassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer herbeigezaubertes Essen ist jetzt noch üppiger.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Blutrote Tinte (8), Ultramarinblaue Tinte (20), Herbeigezaubertes Manabrötchen (20), Puderzucker (5)" }
entries[172451] = { ["name"] = "Schwaches Animapartikel", ["text"] = "\"Ein substanzloses Animadestillat. Es ist zu schwach, um allein genügend Energie zu liefern.\"" }
entries[172453] = { ["name"] = "Gefangenentransferbefehle", ["text"] = "Questgegenstand\n\"In einer alten und unfreundlichen Sprache verfasst.\"" }
entries[172454] = { ["name"] = "Teufelswaren", ["text"] = "Questgegenstand\n\"Exotische Waren für Xem'altan.\"" }
entries[172455] = { ["name"] = "Verhärtete Teufelssplitter", ["text"] = "Questgegenstand\n\"Konzentrierte Macht, praktische Größe.\"" }
entries[172456] = { ["name"] = "Gesplitterter Teufelskern", ["text"] = "Questgegenstand\n\"Ein Bewohner der Schattenlande findet vielleicht einen Weg, diesen Schatz wiederherzustellen.\"" }
entries[172457] = { ["name"] = "Legionsbefehle", ["text"] = "Questgegenstand\n\"Zweifelsohne gefragt bei Strategen der Maldraxxi.\"" }
entries[172458] = { ["name"] = "Abgegriffene Legionsmarke", ["text"] = "Questgegenstand\n\"Vielleicht eine fremde Art von Währung?\"" }
entries[172460] = { ["name"] = "Teufelswickel", ["text"] = "Questgegenstand\n\"Eine Kompresse, durchtränkt mit brennendem Höllenfeuer.\"" }
entries[172462] = { ["name"] = "Verzauberter Zwielichtzauberstab", ["text"] = "Wird beim Anlegen gebunden\nDistanz Zauberstab\n3 - 6 Arkanschaden Geschwindigkeit 2.00\n(2.3 Schaden pro Sekunde)\n+25 Intelligenz\n+6 Ausdauer\n+ 4 Zufallswert 1\n+ 4 Zufallswert 2\nHaltbarkeit 75 / 75\nVerkaufspreis:" }
entries[172463] = { ["name"] = "Geborgene Mogurüstung", ["text"] = "Questgegenstand\n\"Auch wenn sie die Beulen nicht verbergen kann, wird diese Rüstung noch einige Schlachten überstehen.\"" }
entries[172464] = { ["name"] = "Nimblatt", ["text"] = "Questgegenstand\n\"Der bittere Geschmack von Nimblatt täuscht über die starken medizinischen Eigenschaften hinweg.\"" }
entries[172491] = { ["name"] = "Flappi", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
