entries[172494] = { ["name"] = "Götze der Baruk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Verwandelt den Zaubernden für 10 Sek. in Stein, macht ihn somit immun gegen Schaden und heilt ihn pro Sekunde um 5 Gesundheit. Bewegung beendet diesen Effekt. Kann nur in Uldum und im Tal der Ewigen Blüten verwendet werden. (30 Min Abklingzeit)\nVerkaufspreis:" }
