entries[172515] = { ["name"] = "Zuckende Gefängniskäfigrune", ["text"] = "Vision von Sturmwind\nQuestgegenstand\nEinzigartig\n\"Diese veränderliche Rune scheint Euch anzustarren. Sie wurde aus der Tasche eines unaussprechlichen Schreckens erbeutet. Zumindest hofft Ihr inbrünstig, dass es eine Tasche war...\"" }
