entries[172519] = { ["name"] = "Rüstmeisternotiz", ["text"] = "Saison 4 von Battle for Azeroth\nWird beim Aufheben gebunden\n\"Kann gegen eine Trophäe des Kriegsfürsten eingetauscht werden. Geht dafür zu Marschall Gabriel bei den Aschenwinddocks oder Xander Silbermann am Mugambala.\"" }
