entries[172902] = { ["name"] = "Bombenbolawerfer", ["text"] = "Benutzen: Verschießt ein Paar aneinandergebundene Bomben direkt nach vorn, die sich um den ersten getroffenen Gegner wickeln, nach 5 Sek. explodieren und Gegnern in der Nähe dabei 13939 Feuerschaden zufügen. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande (1)" }
entries[172903] = { ["name"] = "Nussknackergranate", ["text"] = "Benutzen: Fügt allen Gegnern in einem Radius von 5 Metern 13939 Naturschaden zu. (5 Min Abklingzeit)" }
entries[172904] = { ["name"] = "Schattenlandmine", ["text"] = "Benutzen: Platziert eine Mine auf dem Boden, die explodiert, wenn ein Gegner auf sie tritt. Dies fügt allen Gegnern innerhalb eines Radius von 5 Metern 13939 Schattenschaden zu und stößt sie zurück. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande (1)" }
entries[172905] = { ["name"] = "Flexible Ektoplasmabrille", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n12 Rüstung\n+18 Intelligenz\n+27 Ausdauer\n+ 18 Zufallswert 1\n+ 18 Zufallswert 2\nHaltbarkeit 85 / 85\nAnlegen: Erhöht Eure Ingenieurskunst der Schattenlande um 20.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst der Schattenlande (1)\nVerkaufspreis:" }
entries[172906] = { ["name"] = "Geerdete Ektoplasmabrille", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n20 Rüstung\n+18 [Beweglichkeit oder Intelligenz]\n+27 Ausdauer\n+ 18 Zufallswert 1\n+ 18 Zufallswert 2\nHaltbarkeit 85 / 85\nAnlegen: Erhöht Eure Ingenieurskunst der Schattenlande um 20.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst der Schattenlande (1)\nVerkaufspreis:" }
entries[172907] = { ["name"] = "Gegliederte Ektoplasmabrille", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n29 Rüstung\n+18 [Beweglichkeit oder Intelligenz]\n+27 Ausdauer\n+ 18 Zufallswert 1\n+ 18 Zufallswert 2\nHaltbarkeit 85 / 85\nAnlegen: Erhöht Eure Ingenieurskunst der Schattenlande um 20.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst der Schattenlande (1)\nVerkaufspreis:" }
entries[172908] = { ["name"] = "Verstärkte Ektoplasmabrille", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n44 Rüstung\n+18 [Stärke oder Intelligenz]\n+27 Ausdauer\n+ 18 Zufallswert 1\n+ 18 Zufallswert 2\nHaltbarkeit 85 / 85\nAnlegen: Erhöht Eure Ingenieurskunst der Schattenlande um 20.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst der Schattenlande (1)\nVerkaufspreis:" }
entries[172910] = { ["name"] = "Dunkelmond-Karte der Rast", ["text"] = "\"Irgendeine Dunkelmond-Karte der Rast. Sammelt das ganze Set, um eine Belohnung zu erhalten.\"" }
entries[172912] = { ["name"] = "Schwungumverteilungsstiefel", ["text"] = "Wird bei Benutzung gebunden\nBenutzen: Leitet einen beträchtlichen Teil des Fallschadens, den Ihr bei Eurem nächsten Sturz erleiden würdet, auf Gegner in der Nähe um. Hält 10 Sek. lang an.\n\nKann nicht in Instanzen verwendet werden. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande (1)\n\"Ermöglicht Euch das Ausführen einer superheroischen Landung!\"\nVerkaufspreis:" }
entries[172914] = { ["name"] = "Gravimetrische Störkanone", ["text"] = "Wird bei Benutzung gebunden\nBenutzen: Destabilisiert die Schwerkraft um einen Zielort, was 10 Sek. lang die Bewegung von Gegnern in der Nähe behindert, sie in zufällige Richtungen schleudert oder sie in die Luft stößt...\n\nsofern keine Fehlzündung eintritt.\nBenötigt Ingenieurskunst der Schattenlande (1)\n\"Wird gelegentlich als \"Schwarzes-Loch-Kanone\" bezeichnet, was jedoch ein unzutreffender Name ist. Eigentlich ist es eher ein Artilleriegeschütz.\"\nVerkaufspreis:" }
entries[172915] = { ["name"] = "533L3N-F4LL3", ["text"] = "Wird bei Benutzung gebunden\nBenutzen: Platziert ein Eindämmungsgerät auf dem Boden, das nach seiner Scharfmachung aktiviert wird, wenn ein Gegner darauf tritt. Der Gegner wird dann für 1 Min. gebannt.\n\nEs sei denn, es tritt eine Fehlzündung ein.\n\nVerringerte Wirksamkeit gegen Spielercharaktere. (3 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande (1)\n\"Mit wem werdet Ihr kommunizieren?!\"\nVerkaufspreis:" }
entries[172917] = { ["name"] = "Gürtelmodifikation: Dimensionswechsler", ["text"] = "Benutzen: Bringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr einen Gegner in Nahkampfreichweite für 5 Sek. in Furcht versetzen könnt.\n\nNur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden.\n\"Man kann nicht angreifen, was man nicht visuell wahrnehmen kann!\"" }
entries[172918] = { ["name"] = "Gürtelmodifikation: Elektrosprung", ["text"] = "Benutzen: Bringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr einen Gegner in Nahkampfreichweite für 5 Sek. in Furcht versetzen könnt.\n\nNur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden.\n\"Wie der Blitz!\"" }
entries[172919] = { ["name"] = "Gürtelmodifikation: Schadensvergelter", ["text"] = "Benutzen: Bringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr einen Gegner in Nahkampfreichweite für 5 Sek. in Furcht versetzen könnt.\n\nNur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden.\n\"Auge um Auge, Zahnrad um Zahnrad.\"" }
entries[172920] = { ["name"] = "Optischer Zielvergrößerer", ["text"] = "Benutzen: Bringt dauerhaft ein Zielfernrohr an einer Distanzwaffe an, sodass manchmal Euer kritischer Trefferwert 12 Sek. lang um 824 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an eine Distanzwaffe wird diese seelengebunden.\n\"Bämm. Kopfschuss.\"\nVerkaufspreis:" }
entries[172921] = { ["name"] = "Infragrünes Reflexzielfernrohr", ["text"] = "Benutzen: Bringt dauerhaft ein Zielfernrohr an einer Distanzwaffe an, sodass manchmal Euer Tempo 12 Sek. lang um 824 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an eine Distanzwaffe wird diese seelengebunden.\n\"Vor mir kann sich niemand verstecken.\"\nVerkaufspreis:" }
entries[172923] = { ["name"] = "Präzisionslebenskraftumkehrer", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n13 - 25 Schaden Geschwindigkeit 3.00\n(6.3 Schaden pro Sekunde)\n+9 Beweglichkeit\n+13 Ausdauer\n+ 9 Zufallswert 1\n+ 9 Zufallswert 2\nHaltbarkeit 85 / 85\n\"Sorgt mit hoher Effizienz dafür, dass gegnerische Kämpfer weniger gesund werden.\"\nVerkaufspreis:" }
entries[172924] = { ["name"] = "Wurmlochgenerator: Schattenlande", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Öffnet ein Wurmloch, das es dem Benutzer ermöglicht, schnell an einen von mehreren Fixpunkten innerhalb der Schattenlande zu reisen. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande (1)\n\"VORSICHT: Ungenaue Befolgung der Sicherheitsrichtlinien kann Folgen haben, wie... Doppeltod? Turbotod? Lebendigkeit?\"\nVerkaufspreis:" }
entries[172925] = { ["name"] = "Gesichtslosenmaske der Verbrannten Brücke", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erschafft bei Bewegung Zonen der Leere hinter Euch, die geistige Gesundheit entziehen.\n\"Nichts verbleibt außer einem leichten Rauchgeruch und einer Erinnerung an Tränen in den Augen.\"" }
entries[172926] = { ["name"] = "Nekrostatischer Mikrokondensator", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Abschluss von Weltquests erhöht Primärwert\n\"Ein optionales Reagenz, das bei der Herstellung eines Rüstungsteils benutzt werden kann, um den Primärwert des Trägers bei Abschluss von Weltquests zu erhöhen.\"\nVerkaufspreis:" }
entries[172928] = { ["name"] = "Hydrodynamische Beschleuniger", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Erhöht die Schwimmgeschwindigkeit\n\"Ein optionales Reagenz, durch das die hergestellte Rüstung die Schwimmgeschwindigkeit des Trägers erhöht.\"\nVerkaufspreis:" }
