entries[173023] = { ["name"] = "Werdet Zeuge: Der Beobachterkodex", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese geprägte Schriftrolle beschreibt die Werte des Mitgefühls und der Pflicht bei der Bestimmung des Schicksals von kürzlich Verstorbenen.\"\n<Zum Lesen rechtsklicken>" }
