entries[173067] = { ["name"] = "Vantusrune: Schloss Nathria", ["text"] = "Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Schloss Nathria ein, was Eure Vielseitigkeit um 1875 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:" }
entries[173068] = { ["name"] = "Vantusrunentechnik: Schloss Nathria", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Schloss Nathria herstellt.\nBenötigt Inschriftenkunde der Schattenlande (100)\nVerkaufspreis:\nVantusrune: Schloss Nathria\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Schloss Nathria ein, was Eure Vielseitigkeit um 1875 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leuchtende Tinte (10), Umbraltinte (10), Stille Tinte , Dunkles Pergament" }
entries[173069] = { ["name"] = "Dunkelmond-Kartenset: Fäulnis", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+28 Intelligenz\nBenutzen: Lässt Energie aus dem Ziel hervorbrechen und verursacht 951 Schattenschaden, die gleichmäßig auf alle Gegner innerhalb von 10 Metern aufgeteilt werden. Die Chance jedes getroffenen Gegners, kritische Treffer durch Euch zu erleiden, wird um 6% bis 13% erhöht. Die Höhe dieses Werts ist von der obenliegenden Karte des Kartensets abhängig. Hält 10 Sek. lang an. (1 Min, 30 Sek. Abklingzeit)\nAnlegen: Mischt im Kampf regelmäßig das Kartenset.\nVerkaufspreis:" }
