entries[173280] = { ["name"] = "Abzeichen der Schwelle des Todes", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Atem der Sterbenden'.\nGroße Macht:\nErgreifende Flammen\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Verbrennt Euer Ziel mit einem Azeritblitz und fügt ihm 3067 Feuerschaden zu. Wenn das Ziel weniger als 20% Gesundheit hat, wird die Abklingzeit um 30 Sek. verringert.\nGeringe Macht:\nTödliche Hiebe\n40 Meter Reichweite\nCa. 10 Procs pro Minute Eure Zauber und Fähigkeiten haben die Chance, Eurem Ziel bei einem Treffer 1244 Feuerschaden zuzufügen .\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[173281] = { ["name"] = "Abzeichen des Todesmals", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Atem der Sterbenden'.\nGroße Macht:\nErgreifende Flammen\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Verbrennt Euer Ziel mit einem Azeritblitz und fügt ihm 3067 Feuerschaden zu. Wenn das Ziel weniger als 20% oder mehr als 80% Gesundheit hat, wird die Abklingzeit um 30 Sek. verringert.\nGeringe Macht:\nTödliche Hiebe\n40 Meter Reichweite\nCa. 10 Procs pro Minute Eure Zauber und Fähigkeiten haben die Chance, Eurem Ziel bei einem Treffer 1244 Feuerschaden zuzufügen und Euch um 50% des verursachten Schadens zu heilen.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[173282] = { ["name"] = "Abzeichen der Todesfreude", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Atem der Sterbenden'.\nErlernt Rang 3 einer Essenz von den Rajani oder dem Abkommen von Uldum auf einem anderen Charakter, um diese Essenz freizuschalten.\nBenötigt einen respektvollen Ruf beim Abkommen von Uldum. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nErgreifende Flammen\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Verbrennt Euer Ziel mit einem Azeritblitz und fügt ihm 3067 Feuerschaden zu. Wenn das Ziel weniger als 20% Gesundheit oder mehr als 80% Gesundheit hat, wird die Abklingzeit um 30 Sek. verringert.\n\nWenn 'Ergreifende Flammen' einen Gegner tötet, wird die Abklingzeit um 5 Sek. verringert und 'Ergreifende Flammen' verursacht beim nächsten Einsatz 100% mehr Schaden.\nGeringe Macht:\nTödliche Hiebe\n40 Meter Reichweite\nCa. 10 Procs pro Minute Eure Zauber und Fähigkeiten haben die Chance, Eurem Ziel bei einem Treffer 1244 Feuerschaden zuzufügen und Euch um 50% des verursachten Schadens zu heilen.\n\nWenn Euer Ziel weniger als 20% Gesundheit hat, ist die Chance auf zusätzlichen Schaden um 400% erhöht.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.\n\"Ein Flüstern über das, was Euch erwartet.\"" }
entries[173283] = { ["name"] = "Abzeichen des erstklassigen Todes", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Atem der Sterbenden'.\nGroße Macht:\nErgreifende Flammen\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Verbrennt Euer Ziel mit einem Azeritblitz und fügt ihm 3067 Feuerschaden zu. Wenn das Ziel weniger als 20% Gesundheit oder mehr als 80% Gesundheit hat, wird die Abklingzeit um 30 Sek. verringert.\n\nWenn 'Ergreifende Flammen' einen Gegner tötet, wird die Abklingzeit um 5 Sek. verringert und 'Ergreifende Flammen' verursacht beim nächsten Einsatz 100% mehr Schaden.\nGeringe Macht:\nTödliche Hiebe\n40 Meter Reichweite\nCa. 10 Procs pro Minute Eure Zauber und Fähigkeiten haben die Chance, Eurem Ziel bei einem Treffer 1244 Feuerschaden zuzufügen und Euch um 50% des verursachten Schadens zu heilen.\n\nWenn Euer Ziel weniger als 20% Gesundheit hat, ist die Chance auf zusätzlichen Schaden um 400% erhöht.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
