entries[173288] = { ["name"] = "Überquellende Azeritgeode", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Inspirierender Funke'.\nGroße Macht:\nRuhmreicher Moment\n40 Meter Reichweite Wirken in 1.5 sek. 1 min Abklingzeit Entfesselt eine Energiewelle aus Eurem Herz von Azeroth und erhöht bei allen Gruppenmitgliedern innerhalb von 15 Metern den Schaden, den sie mit Azeritessenzen verursachen, für die nächsten 10 Sek. um 45%.\nGeringe Macht:\nVereinte Kräfte\n40 Meter Reichweite\nCa. 3 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, [das Tempo von Euch und 2 anderen Verbündeten][Euer Tempo] 8 Sek. lang um 30 zu erhöhen und die Abklingzeit der bei [Euch und 2 anderen Verbündeten][Euch] aktuell eingesetzten großen Essenz um 1.0 Sek. zu verringern.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[173289] = { ["name"] = "Pulsierende Azeritgeode", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Inspirierender Funke'.\nGroße Macht:\nRuhmreicher Moment\n40 Meter Reichweite Wirken in 1.5 sek. 1 min Abklingzeit Entfesselt eine Energiewelle aus Eurem Herz von Azeroth und erhöht bei allen Gruppenmitgliedern innerhalb von 15 Metern den Schaden, den sie mit Azeritessenzen verursachen, für die nächsten 20 Sek. um 45%.\nGeringe Macht:\nVereinte Kräfte\n40 Meter Reichweite\nCa. 4 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Tempo von Euch und 1 anderem Verbündeten 8 Sek. lang um 30 zu erhöhen und die Abklingzeit der bei Euch und 1 anderem Verbündeten aktuell eingesetzten großen Essenz um 1.0 Sek. zu verringern.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[173290] = { ["name"] = "Beflügelnde Azeritgeode", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Inspirierender Funke'.\nErlernt Rang 3 einer Essenz aus Verstörenden Visionen auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nRuhmreicher Moment\n40 Meter Reichweite Wirken in 1.5 sek. 1 min Abklingzeit Entfesselt eine Energiewelle aus Eurem Herz von Azeroth und erhöht bei allen Gruppenmitgliedern innerhalb von 15 Metern den Schaden, den sie mit Azeritessenzen verursachen, für die nächsten 20 Sek. um 45%. Erhöht währenddessen außerdem ihre Geschwindigkeit um 64 .\nGeringe Macht:\nVereinte Kräfte\n40 Meter Reichweite\nCa. 4 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Tempo von Euch und 2 anderen Verbündeten 8 Sek. lang um 30 zu erhöhen und die Abklingzeit der bei Euch und 2 anderen Verbündeten aktuell eingesetzten großen Essenz um 1.0 Sek. zu verringern.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[173291] = { ["name"] = "Leuchtende Azeritgeode", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Inspirierender Funke'.\nGroße Macht:\nRuhmreicher Moment\n40 Meter Reichweite Wirken in 1.5 sek. 1 min Abklingzeit Entfesselt eine Energiewelle aus Eurem Herz von Azeroth und erhöht bei allen Gruppenmitgliedern innerhalb von 15 Metern den Schaden, den sie mit Azeritessenzen verursachen, für die nächsten 20 Sek. um 45%. Erhöht währenddessen außerdem ihre Geschwindigkeit um 64 .\nGeringe Macht:\nVereinte Kräfte\n40 Meter Reichweite\nCa. 4 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Tempo von Euch und 2 anderen Verbündeten 8 Sek. lang um 30 zu erhöhen und die Abklingzeit der bei Euch und 2 anderen Verbündeten aktuell eingesetzten großen Essenz um 1.0 Sek. zu verringern.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[173292] = { ["name"] = "Traumfängeranima", ["text"] = "Questgegenstand\nEinzigartig\n\"Zerstäubte Anima, die an dünnen Seidenfäden klebt. Vorsichtig behandeln.\"" }
entries[173293] = { ["name"] = "Phiole der Selbstbewahrung", ["text"] = "Vision der Wirbelnden Sande\nBenutzen: Opfert 10% Gesundheit, um 100 geistige Gesundheit wiederherzustellen. (5 Min Abklingzeit)\n\"Ein geringer Preis dafür, dass das Flüstern vorübergehend aufhört.\"" }
entries[173296] = { ["name"] = "Rikkis Tropenhelm", ["text"] = "Benutzen: Lehrt Euch, wie man Rikki das Seidenäffchen beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[173297] = { ["name"] = "Zügel des Dünenstreifers des Forschers", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der mürrische Dünenstreifer kann problemlos einen Forschertrupp zu den nächsten Ruinen und zurück tragen, ohne sich ausruhen zu müssen.\"\nWerbt einen Freund" }
entries[173298] = { ["name"] = "Zertifikat des Forschers", ["text"] = "Benutzen: Gewährt den Titel \"Berühmter Forscher\".\nVerkaufspreis:" }
entries[173299] = { ["name"] = "Schlüssel zum Dschungelhopser des Forschers", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Kann ja immer mal passieren, dass man in der Mitte eines unerforschten Sumpfes notlanden muss, um sich Zugang zu einem uralten Tempel zu verschaffen.\"\nWerbt einen Freund" }
