entries[173307] = { ["name"] = "Verstärkte Rüstung", ["text"] = "Questgegenstand\n\"Robuste Ersatzrüstung für einen Phalynx.\"" }
entries[173308] = { ["name"] = "Mal des wilden Dienstes", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Stärke des Wächters'.\nGroße Macht:\nWachsamer Beschützer\nSofort 2 min Abklingzeit Verspottet alle Gegner in der Nähe und zwingt sie 6 Sek. lang, Euch anzugreifen.\nGeringe Macht:\nDurchhaltevermögen\nSpeichert alle 2 Sek. 188 Heilung bis zu einem Maximum von (Gesamtgesundheit * 0.1). Wenn Ihr einem Angriff ausweicht oder ihn pariert, werdet Ihr um den Gesamtwert der gespeicherten Heilung geheilt.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.\n\"Man sollte Konfrontationen willkommen heißen, anstatt sich vor ihnen zu verstecken.\"" }
entries[173309] = { ["name"] = "Technik des Wassertänzers", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Stärke des Wächters'.\nGroße Macht:\nWachsamer Beschützer\nSofort 2 min Abklingzeit Verspottet alle Gegner in der Nähe und zwingt sie 6 Sek. lang, Euch anzugreifen. Erhöht Eure Ausweichchance 6 Sek. lang um 15%.\nGeringe Macht:\nDurchhaltevermögen\nSpeichert alle 2 Sek. [ 158 * (1 + Vielseitigkeit) * (1.25)] Heilung bis zu einem Maximum von (Gesamtgesundheit * 0.1). Wenn Ihr einem Angriff ausweicht oder ihn pariert, werdet Ihr um den Gesamtwert der gespeicherten Heilung geheilt.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.\n\"Schnell... und plötzlich!\"" }
entries[173310] = { ["name"] = "Handbuch der unausgewogenen Taktiken", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Stärke des Wächters'.\nErlernt Rang 3 einer Essenz aus Verstörenden Visionen auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nWachsamer Beschützer\nSofort 2 min Abklingzeit Verspottet alle Gegner in der Nähe und zwingt sie 6 Sek. lang, Euch anzugreifen. Erhöht Eure Ausweichchance 6 Sek. lang um 15%.\n\nZiele, die von Eurem 'Wachsamer Beschützer' betroffen sind, erleiden durch Euch 50% mehr Schaden.\nGeringe Macht:\nDurchhaltevermögen\nSpeichert alle 2 Sek. [ 158 * (1 + Vielseitigkeit) * (1.25)] Heilung bis zu einem Maximum von (Gesamtgesundheit * 0.1). Wenn Ihr einem Angriff ausweicht oder ihn pariert, werdet Ihr um den Gesamtwert der gespeicherten Heilung geheilt.\n\nDie Maximalgesundheit aller Spielercharaktere mit Tankspezialisierung in Eurer Gruppe oder Eurem Schlachtzug wird um 3% erhöht. Stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
